package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.net.MalformedURLException;
import java.net.URL;
import java.util.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.parser.Parser;
import org.jsoup.select.NodeTraversor;
import org.jsoup.select.NodeVisitor;
import org.junit.*;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.ExpectedException;
import static org.junit.Assert.*;

public class Node_hasAttr_TriageGen0Test {

    @Rule
    public ExpectedException thrown = ExpectedException.none();

    /**
     * Test that hasAttr throws NullPointerException when attributeKey is null.
     * This covers the Validate.notNull(attributeKey) branch/line.
     */
    @Test
    public void testHasAttr_NullKey_ThrowsException() {
        Node node = new Element(""); // Using Element as a concrete implementation of Node
        thrown.expect(NullPointerException.class);
        node.hasAttr(null);
    }

    /**
     * Test that hasAttr returns true when the attribute exists.
     */
    @Test
    public void testHasAttr_AttributeExists_ReturnsTrue() {
        Element element = new Element("");
        element.attr("key", "value");

        assertTrue("Should return true when the attribute exists", element.hasAttr("key"));
    }

    /**
     * Test that hasAttr returns false when the attribute does not exist.
     */
    @Test
    public void testHasAttr_AttributeDoesNotExist_ReturnsFalse() {
        Element element = new Element("");

        assertFalse("Should return false when the attribute does not exist", element.hasAttr("nonexistent"));
    }

    /**
     * Test that hasAttr returns true for an empty string attribute key if it was set.
     */
    @Test
    public void testHasAttr_EmptyStringKey_ReturnsTrue() {
        Element element = new Element("");
        element.attr("", "emptyValue");

        assertTrue("Should return true for an empty string key if it exists", element.hasAttr(""));
    }

    /**
     * Test that hasAttr returns false for an empty string attribute key if it was not set.
     */
    @Test
    public void testHasAttr_EmptyStringKey_ReturnsFalse() {
        Element element = new Element("");

        assertFalse("Should return false for an empty string key if it does not exist", element.hasAttr(""));
    }
}

/**
 * Helper subclass to allow testing the protected Node constructor.
 * Since Node is abstract, we use Element (a standard Jsoup implementation) 
 * or a minimal concrete implementation.
 */
class Element extends Node {
    private final String tagName;

    public Element(String tagName) {
        super();
        this.tagName = tagName;
    }

    @Override
    public String nodeName() {
        return tagName;
    }
}
